def apply_beam(pts, axis, index, side, h=18,w=18):
    # input set of coords; keep on cut line; other portions to corner based their side of beam
    line={(r,c) for r,c in pts if (r==index if axis=='h' else c==index)}
    before={(r,c) for r,c in pts if (r<index if axis=='h' else c<index)}
    after={(r,c) for r,c in pts if (r>index if axis=='h' else c>index)}
    # side is source edge: left for h or top for v. map two sections to adjacent corners
    def shift(group, corner):
        if not group:return set()
        rs=[p[0] for p in group]; cs=[p[1] for p in group]
        dr= -min(rs) if corner[0]=='T' else h-1-max(rs)
        dc= -min(cs) if corner[1]=='L' else w-1-max(cs)
        return {(r+dr,c+dc) for r,c in group}
    if axis=='h':
        a=shift(before,('T','L' if side=='L' else 'R'))
        b=shift(after,('B','L' if side=='L' else 'R'))
    else:
        a=shift(before,('T','L' if side=='T' else 'R')) # before is left side if vertical; bug corner y same top; x by side of line
        b=shift(after,('T','R' if side=='T' else 'L'))
    return line|a|b
